  assert.equal(row("saved-after").stdout,"24\n22\n6.0\n");
  assert.equal(row("new-card-before").stdout,"30\n25\n");assert.equal(row("new-card-after").stdout,"34\n29\n");assert.equal(row("new-grouping").stdout,"15\n20\n3.0\n");
